", direction=None, fact=None, file_name='/workspace/sandbox/skills/building-accessible-ui/simple-contact-form--framework-react--style-modern--validation-message-absent/claude-haiku-4.5__s0/test-a11y-interactive.js', full_command_text=None, hook_message=None, intention='Edit file', new_file_contents="const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');
const axeSource = require('axe-core').source;

(async () => {
    const browser = await chromium.launch();
    const page = await browser.newPage();

    const htmlPath = path.join(__dirname, 'index.html');
    const htmlContent = fs.readFileSync(htmlPath, 'utf8');

    await page.setContent(htmlContent, { waitUntil: 'load' });

    // Simulate user interaction: trigger validation by focusing and blurring
    await page.locator('#fullName').focus();
    await page.locator('#fullName').evaluate(el => el.blur());
    await page.locator('#email').focus();
    await page.locator('#email').evaluate(el => el.blur());

    await page.addScriptTag({ content: axeSource });

    const results = await page.evaluate(() => window.axe.run());
    await browser.close();

    const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
    const bp = results.violations.filter(v => v.tags.includes('best-practice'));

    console.log('=== ACCESSIBILITY TEST WITH VALIDATION STATE ===\n');
    console.log(`Passes: ${results.passes.length}`);
    console.log(`WCAG Violations: ${wcag.length}`);
    console.log(`Best Practice Warnings: ${bp.length}\n`);

    if (wcag.length > 0) {
        console.log('WCAG VIOLATIONS:');
        wcag.forEach(v => {
            console.log(`\n- ${v.id} (${v.impact})`);
            console.log(`  ${v.description}`);
            console.log(`  Targets: ${v.nodes.map(n => n.target).join(', ')}`);
            console.log(`  Help: ${v.help}`);
        });
    } else {
        console.log('✅ No WCAG violations found');
    }

    if (bp.length > 0) {
        console.log('\nBEST PRACTICE WARNINGS:');
        bp.forEach(v => {
            console.log(`\n- ${v.id}`);
            console.log(`  ${v.description}`);
        });
    }

    process.exit(wcag.length > 0 ? 1 : 0);
})();
